import React, { useState, useEffect, useRef } from 'react';
import './weatherWidget.css';

const WeatherWidget = ({
  initialWeatherData = null,
  initialLocation = 'Current Location',
  onClose,
  apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5001/chat',
  sessionId = null
}) => {
  // State for weather data
  const [weather, setWeather] = useState({
    temperature: '--',
    feelsLike: '--',
    condition: '--',
    conditionEmoji: '--',
    icon: '--',
    high: '--',
    low: '--',
    humidity: '--',
    uvIndex: '--',
    visibility: '--',
    windSpeed: '--',
    windDirection: '--',
    pressure: '--',
    dewPoint: '--',
    sunrise: '--:--',
    sunset: '--:--',
    location: initialLocation
  });

  // State for widget controls
  const [isVisible, setIsVisible] = useState(true);
  const [position, setPosition] = useState({ x: 100, y: 100 });
  const [size, setSize] = useState('normal'); // 'small', 'normal', 'large'
  const [isLoading, setIsLoading] = useState(false);

  // Refs for drag and resize functionality
  const widgetRef = useRef(null);
  const dragRef = useRef({ isDragging: false, offsetX: 0, offsetY: 0 });
  const resizeRef = useRef({ isResizing: false });
  const intervalRef = useRef(null);
  const currentLocationRef = useRef(initialLocation);

  // Weather cache
  const [weatherCache, setWeatherCache] = useState({});
  const WEATHER_CACHE_DURATION = 300000; // 5 minutes

  // Load initial weather data if provided
  useEffect(() => {
    if (initialWeatherData) {
      setWeather(prev => ({ ...prev, ...initialWeatherData }));
      currentLocationRef.current = initialLocation;
      startWeatherUpdates(initialLocation);
    }
  }, [initialWeatherData, initialLocation]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, []);

  // Handle drag start
  const handleDragStart = (e) => {
    if (e.target.classList.contains('drag-handle') || e.target.closest('.drag-handle')) {
      dragRef.current.isDragging = true;
      const rect = widgetRef.current.getBoundingClientRect();
      dragRef.current.offsetX = e.clientX - rect.left;
      dragRef.current.offsetY = e.clientY - rect.top;
      document.addEventListener('mousemove', handleDragMove);
      document.addEventListener('mouseup', handleDragEnd);
    }
  };

  // Handle drag move
  const handleDragMove = (e) => {
    if (dragRef.current.isDragging) {
      const newX = e.clientX - dragRef.current.offsetX;
      const newY = e.clientY - dragRef.current.offsetY;
      setPosition({ x: newX, y: newY });
    }
  };

  // Handle drag end
  const handleDragEnd = () => {
    dragRef.current.isDragging = false;
    document.removeEventListener('mousemove', handleDragMove);
    document.removeEventListener('mouseup', handleDragEnd);
  };

  // Handle resize start
  const handleResizeStart = (e) => {
    e.stopPropagation();
    resizeRef.current.isResizing = true;
    document.addEventListener('mousemove', handleResizeMove);
    document.addEventListener('mouseup', handleResizeEnd);
  };

  // Handle resize move
  const handleResizeMove = (e) => {
    if (resizeRef.current.isResizing) {
      // In a real implementation, we would handle resizing here
      // For now, we'll just prevent default behavior
    }
  };

  // Handle resize end
  const handleResizeEnd = () => {
    resizeRef.current.isResizing = false;
    document.removeEventListener('mousemove', handleResizeMove);
    document.removeEventListener('mouseup', handleResizeEnd);
  };

  // Increase widget size
  const increaseWidgetSize = () => {
    setSize(prev => {
      if (prev === 'small') return 'normal';
      if (prev === 'normal') return 'large';
      return 'large'; // Stay at large if already large
    });
  };

  // Decrease widget size
  const decreaseWidgetSize = () => {
    setSize(prev => {
      if (prev === 'large') return 'normal';
      if (prev === 'normal') return 'small';
      return 'small'; // Stay at small if already small
    });
  };

  // Hide the widget
  const hideWeatherDisplay = () => {
    stopWeatherUpdates();
    setIsVisible(false);
    if (onClose) onClose();
  };

  // Get UV level description
  const getUVLevel = (uvIndex) => {
    if (uvIndex <= 2) return 'Low';
    if (uvIndex <= 5) return 'Moderate';
    if (uvIndex <= 7) return 'High';
    if (uvIndex <= 10) return 'Very High';
    return 'Extreme';
  };

  // Update weather display with new data
  const updateWeatherDisplay = (newWeatherData) => {
    setWeather(prev => ({
      ...prev,
      ...newWeatherData,
      uvLevel: getUVLevel(newWeatherData.uvIndex)
    }));
  };

  // Fetch weather data for a specific location
  const getWeatherForLocation = async (location, forceRefresh = false) => {
    const cacheKey = location.toLowerCase();
    const now = Date.now();

    // Check cache unless force refresh
    if (!forceRefresh && weatherCache[cacheKey] && (now - weatherCache[cacheKey].timestamp < WEATHER_CACHE_DURATION)) {
      console.log(`📋 Using cached weather for ${location}`);
      return weatherCache[cacheKey].data;
    }

    setIsLoading(true);

    try {
      console.log(`🌐 Making API request for weather in: ${location}`);
      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Cache-Control': 'no-cache, no-store, must-revalidate',
          'Pragma': 'no-cache'
        },
        body: JSON.stringify({
          message: `What is the current weather in ${location}? Please provide comprehensive weather data including temperature, condition, humidity, wind, pressure, UV index, visibility, sunrise/sunset times, and dew point. Format as WEATHER_DATA: [JSON data]. Timestamp: ${Date.now()}`,
          session_id: sessionId
        })
      });

      const data = await response.json();
      console.log(`📡 Weather API response for ${location}:`, data.response?.substring(0, 100) + '...');

      if (data.response) {
        // Check if we have weather data format
        if (data.response.includes('WEATHER_DATA:')) {
          const parts = data.response.split('WEATHER_DATA:');
          const weatherJson = parts[1].trim();
          console.log(`🌤️ Found weather data: ${weatherJson}`);

          try {
            const weatherData = JSON.parse(weatherJson);

            // Cache the weather data
            setWeatherCache(prev => ({
              ...prev,
              [cacheKey]: {
                data: weatherData,
                timestamp: now
              }
            }));

            return weatherData;
          } catch (parseError) {
            console.error('❌ Failed to parse weather JSON:', parseError);
          }
        }

        // Fallback: Try to extract weather from text response
        const weatherData = extractWeatherFromText(data.response, location);
        if (weatherData) {
          setWeatherCache(prev => ({
            ...prev,
            [cacheKey]: {
              data: weatherData,
              timestamp: now
            }
          }));
          return weatherData;
        }
      }
    } catch (error) {
      console.error(`❌ Error getting weather for ${location}:`, error);
    } finally {
      setIsLoading(false);
    }

    console.error(`❌ Failed to get weather for: ${location}`);
    return null;
  };

  // Extract weather information from text response
  const extractWeatherFromText = (text, location) => {
    // Extract weather information from AI text response
    const tempMatch = text.match(/(\d+)°?F?/i);
    const conditionMatch = text.match(/(sunny|cloudy|rainy|clear|overcast|partly cloudy|scattered clouds|thunderstorm|light rain)/i);
    const humidityMatch = text.match(/(\d+)%/);
    const windMatch = text.match(/(\d+)\s*(?:mph|km\/h)/i);

    if (tempMatch) {
      const temp = parseInt(tempMatch[1]);
      const condition = conditionMatch ? conditionMatch[1] : 'Unknown';
      const humidity = humidityMatch ? parseInt(humidityMatch[1]) : 50;
      const windSpeed = windMatch ? parseInt(windMatch[1]) : 10;

      // Generate mock comprehensive data based on extracted info
      return generateMockWeatherData(temp, condition, humidity, windSpeed, location);
    }

    return null;
  };

  // Generate mock weather data when needed
  const generateMockWeatherData = (temp, condition, humidity, windSpeed, location) => {
    const conditions = {
      'sunny': { icon: '☀️', emoji: '☀️' },
      'cloudy': { icon: '☁️', emoji: '☁️' },
      'rainy': { icon: '🌧️', emoji: '🌧️' },
      'clear': { icon: '🌤️', emoji: '🌤️' },
      'overcast': { icon: '☁️', emoji: '☁️' },
      'partly cloudy': { icon: '⛅', emoji: '⛅' },
      'scattered clouds': { icon: '⛅', emoji: '🌪️' },
      'thunderstorm': { icon: '⛈️', emoji: '⛈️' },
      'light rain': { icon: '🌦️', emoji: '🌦️' }
    };

    const conditionInfo = conditions[condition.toLowerCase()] || { icon: '🌤️', emoji: '🌤️' };
    const windDirections = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
    const windDirection = windDirections[Math.floor(Math.random() * windDirections.length)];

    // Generate realistic sunrise/sunset times
    const sunriseHour = Math.floor(Math.random() * 3) + 6; // 6-8 AM
    const sunriseMinute = Math.floor(Math.random() * 60);
    const sunsetHour = Math.floor(Math.random() * 3) + 18; // 6-8 PM
    const sunsetMinute = Math.floor(Math.random() * 60);

    return {
      temperature: temp,
      feelsLike: temp + Math.round(Math.random() * 8 - 4),
      condition: condition,
      icon: conditionInfo.icon,
      conditionEmoji: conditionInfo.emoji,
      high: temp + Math.round(Math.random() * 10 + 5),
      low: temp - Math.round(Math.random() * 15 + 5),
      humidity: humidity,
      uvIndex: Math.round(Math.random() * 10),
      visibility: Math.round(Math.random() * 10 + 5), // 5-15 miles
      windSpeed: windSpeed,
      windDirection: windDirection,
      pressure: (29.5 + Math.random() * 1.5).toFixed(2), // 29.5-31.0 inches
      dewPoint: temp - Math.round(Math.random() * 20 + 10),
      sunrise: `${sunriseHour.toString().padStart(2, '0')}:${sunriseMinute.toString().padStart(2, '0')}`,
      sunset: `${sunsetHour.toString().padStart(2, '0')}:${sunsetMinute.toString().padStart(2, '0')}`,
      location: location
    };
  };

  // Start weather updates
  const startWeatherUpdates = (location) => {
    // Stop any existing weather updates
    stopWeatherUpdates();

    if (!location) {
      console.warn('No location provided for weather updates');
      return;
    }

    currentLocationRef.current = location;
    console.log(`🌤️ Starting weather updates for: ${location}`);

    // Update weather every 5 minutes
    intervalRef.current = setInterval(async () => {
      if (currentLocationRef.current) {
        console.log(`🌤️ Refreshing weather for ${currentLocationRef.current}...`);

        try {
          const weatherData = await getWeatherForLocation(currentLocationRef.current, true);
          if (weatherData) {
            updateWeatherDisplay(weatherData);
          }
        } catch (error) {
          console.error('❌ Weather refresh error:', error);
        }
      }
    }, 300000); // 5 minutes
  };

  // Stop weather updates
  const stopWeatherUpdates = () => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
    currentLocationRef.current = null;
    console.log('⏹️ Weather updates stopped');
  };

  // If widget is not visible, don't render anything
  if (!isVisible) {
    return null;
  }

  // Calculate dynamic styles based on size
  const sizeClasses = {
    small: 'widget-size-small',
    normal: 'widget-size-normal',
    large: 'widget-size-large'
  };

  const widgetStyle = {
    left: `${position.x}px`,
    top: `${position.y}px`,
    transform: `scale(${size === 'small' ? 0.8 : size === 'large' ? 1.2 : 1})`
  };

  return (
    <div
      className={`weather-display widget-draggable ${sizeClasses[size]}`}
      id="weatherDisplay"
      ref={widgetRef}
      style={widgetStyle}
    >
      {/* Corner brackets */}
      <div className="corner-top-right"></div>
      <div className="corner-bottom-left"></div>

      {/* Drag handle */}
      <div className="drag-handle" onMouseDown={handleDragStart}></div>

      {/* Widget Controls */}
      <div className="widget-controls">
        <div
          className="widget-control-btn"
          onClick={increaseWidgetSize}
          title="Make Bigger"
        >
          ⧨
        </div>
        <div
          className="widget-control-btn"
          onClick={decreaseWidgetSize}
          title="Make Smaller"
        >
          ⧩
        </div>
        <div
          className="widget-control-btn"
          onClick={hideWeatherDisplay}
          title="Close"
        >
          ⧬
        </div>
      </div>

      {/* Resize handle */}
      <div className="resize-handle" onMouseDown={handleResizeStart}></div>

      {/* Weather label */}
      <div className="weather-label">WEATHER</div>

      {/* Main temperature and condition */}
      <div className="weather-main">
        <div className="weather-temp-section">
          <div className="weather-temp" id="weatherTemp">{weather.temperature}°F</div>
          <div className="weather-feels-like" id="weatherFeelsLike">Feels like {weather.feelsLike}°F</div>
        </div>
        <div className="weather-icon-main" id="weatherIcon">{weather.icon}</div>
      </div>

      <div className="weather-condition" id="weatherCondition">
        <span className="weather-condition-emoji">{weather.conditionEmoji}</span>
        <span>{weather.condition}</span>
      </div>

      {/* Weather details */}
      <div className="weather-details">
        <div className="weather-detail-item">
          <div className="weather-detail-label">High/Low</div>
          <div className="weather-detail-value" id="weatherHighLow">{weather.high}° / {weather.low}°</div>
        </div>
        <div className="weather-detail-item">
          <div className="weather-detail-label">Humidity</div>
          <div className="weather-detail-value" id="weatherHumidity">
            <span className="weather-detail-emoji">💧</span>
            <span>{weather.humidity}%</span>
          </div>
        </div>
        <div className="weather-detail-item">
          <div className="weather-detail-label">UV Index</div>
          <div className="weather-detail-value" id="weatherUV">{weather.uvIndex} {getUVLevel(weather.uvIndex)}</div>
        </div>
        <div className="weather-detail-item">
          <div className="weather-detail-label">Visibility</div>
          <div className="weather-detail-value" id="weatherVisibility">{weather.visibility} mi</div>
        </div>
      </div>

      {/* Extended details */}
      <div className="weather-extended">
        <div className="weather-extended-item">
          <div className="weather-extended-label">Wind</div>
          <div className="weather-extended-value" id="weatherWind">
            <span className="weather-extended-emoji">💨</span>
            <span>{weather.windSpeed} mph {weather.windDirection}</span>
          </div>
        </div>
        <div className="weather-extended-item">
          <div className="weather-extended-label">Pressure</div>
          <div className="weather-extended-value" id="weatherPressure">{weather.pressure} in</div>
        </div>
        <div className="weather-extended-item">
          <div className="weather-extended-label">Dew Point</div>
          <div className="weather-extended-value" id="weatherDewPoint">{weather.dewPoint}°F</div>
        </div>
      </div>

      {/* Sun times section */}
      <div className="weather-sun-times">
        <div className="weather-sun-item">
          <div className="weather-sun-label">Sunrise</div>
          <div className="weather-sun-value" id="weatherSunrise">
            <span className="weather-sun-emoji">🌅</span>
            <span>{weather.sunrise}</span>
          </div>
        </div>
        <div className="weather-sun-item">
          <div className="weather-sun-label">Sunset</div>
          <div className="weather-sun-value" id="weatherSunset">
            <span className="weather-sun-emoji">🌇</span>
            <span>{weather.sunset}</span>
          </div>
        </div>
      </div>

      <div className="weather-location" id="weatherLocation">{weather.location}</div>

      {/* Loading indicator */}
      {isLoading && (
        <div className="loading-overlay">
          <div className="loading-spinner">Loading...</div>
        </div>
      )}
    </div>
  );
};

export default WeatherWidget;
